INSERT INTO public.page_contents (id, page_key, language, content, seo_title, seo_description, seo_keywords, updated_at) VALUES
	(4, 'for-student', 'en', '{"hero_title": "For Students", "intro_body": "<p>Arriving in a new country is exciting — but finding a safe, affordable place to live shouldn''t be stressful. MillionStay specialises in helping international students find quality accommodation in Melbourne, with a process designed around your needs.</p><p>We work directly with universities, migration agents and student support services across Melbourne to make your transition as smooth as possible. From the moment you enquire to the day you check out, our multilingual team is by your side.</p><p>Our rooms are located near Melbourne''s leading universities — University of Melbourne, RMIT, Swinburne, Monash, Deakin and more — in well-connected, safe suburban neighbourhoods.</p>", "cta_primary": "Browse Rooms", "intro_title": "YOUR HOME AWAY FROM HOME", "cta_secondary": "Send Enquiry", "hero_subtitle": "Overseas Student Program", "feature_1_body": "Every room is personally inspected by our team before listing. No scams, no surprises.", "feature_2_body": "Our team speaks English, Korean, Chinese, Japanese and Thai. We''re here to help in your language.", "feature_3_body": "Stay from 4 to 24 weeks. No long-term leases, no stress — just flexibility to match your study schedule.", "feature_4_body": "High-speed Wi-Fi, electricity, water and gas included in your weekly rate. No surprise utility bills.", "hero_image_url": "", "feature_1_title": "Verified & Safe Rooms", "feature_2_title": "Multilingual Support", "feature_3_title": "Flexible Stay Plans", "feature_4_title": "Bills Included"}', 'Student Accommodation Melbourne — MillionStay', 'Find safe, affordable student rooms near Melbourne''s top universities. Flexible 1–6 month plans, all bills included, multilingual support.', 'student accommodation Melbourne, rooms for international students, university housing Melbourne, furnished student rooms', '2026-04-16 03:00:39.156+00'),
	(5, 'for-agent', 'en', '{"how_body": "<h3>01 — Apply to Partner</h3><p>Complete our agent registration form. We''ll review your application and respond within 2 business days.</p><h3>02 — Get Approved &amp; Onboarded</h3><p>Once approved, you''ll receive access to our agent portal, property inventory and co-branded materials.</p><h3>03 — Refer &amp; Earn</h3><p>Refer clients to MillionStay and track every booking. Commissions are paid promptly upon successful check-in.</p>", "cta_title": "AGENT REGISTRATION", "how_title": "HOW TO JOIN", "cta_button": "Apply to Partner", "hero_title": "For Agent", "intro_body": "<p>Are you a migration agent, education consultant or student recruitment agency? MillionStay invites you to join our growing partner network and earn commissions by connecting your clients with premium Melbourne accommodation.</p><p>We understand the challenges international students face when relocating to Melbourne. Our verified properties, multilingual team and seamless booking process make us the most trusted referral partner for student housing in the city.</p><p>Whether you work with students from Korea, China, Japan, Thailand, India or beyond — MillionStay has the right accommodation and the right support for every client profile.</p>", "intro_title": "PARTNER WITH MILLIONSTAY", "hero_subtitle": "Partner Program", "benefit_1_body": "Earn industry-leading referral commissions for every successful booking. Paid promptly upon guest check-in.", "benefit_2_body": "Access a wide international student market spanning Korea, China, Japan, Thailand and beyond.", "benefit_3_body": "Track your referrals, commissions and booking statuses through our dedicated agent portal.", "benefit_1_title": "Competitive Commission", "benefit_2_title": "Multilingual Clients", "benefit_3_title": "Real-time Dashboard"}', 'Agent Partner Program — MillionStay Melbourne', 'Join MillionStay''s agent partner network. Earn competitive commissions referring international students to Melbourne''s top student accommodation.', 'migration agent Melbourne, student accommodation referral, agent partner program, commission accommodation Melbourne', '2026-04-16 03:00:39.164+00'),
	(6, 'about', 'en', '{"team_body": "<p>Our small but dedicated team brings together expertise in property management, student services and international relations.</p><p><strong>Sarah Johnson</strong> — Founder &amp; CEO. Sarah founded MillionStay in 2015 with a vision to transform student accommodation in Melbourne.</p><p><strong>David Kim</strong> — Operations Manager. David oversees our property network and ensures every room meets our strict quality standards.</p><p><strong>Mia Chen</strong> — Student Relations. Mia supports our international students from enquiry to check-out, in English, Chinese and Korean.</p>", "hero_title": "About Us", "team_title": "Our Team", "mission_body": "<p>MillionStay was founded with a simple mission: to make accommodation in Melbourne genuinely accessible and welcoming for international students and digital nomads. We know that finding a safe, comfortable, and affordable home in a new country is one of the biggest challenges you''ll face — and we''re here to make it easier.</p><p>Our multilingual team (English, Korean, Chinese, Japanese and Thai) works every day to match students with the right rooms, handle paperwork, and ensure every guest feels at home from the moment they arrive.</p><p>We offer flexible stay plans from 1 to 6 months, quality-verified rooms across Melbourne''s best student suburbs, and personal support throughout your entire stay. No hidden fees, no stress — just a great place to call home.</p>", "value_1_body": "We believe everyone deserves safe, affordable accommodation — regardless of their background or language.", "value_2_body": "Every property we list is personally verified by our team. What you see is what you get.", "value_3_body": "We build lasting relationships with our tenants, supporting them throughout their entire Melbourne journey.", "values_title": "Our Values", "hero_subtitle": "Who we are", "mission_title": "GET TO KNOW US", "value_1_title": "Accessibility", "value_2_title": "Trust", "value_3_title": "Community"}', 'About MillionStay — Student Accommodation Melbourne', 'Learn about MillionStay — founded to provide safe, affordable, multilingual student accommodation across Melbourne since 2015.', 'about MillionStay, student accommodation company Melbourne, multilingual property management', '2026-04-16 03:00:39.172+00'),
	(2, 'home', 'ko', '{"why_body": "<p>새로운 나라에서 안전하고 편안하며 저렴한 숙소를 찾는 것은 가장 큰 도전 중 하나입니다. MillionStay는 바로 그 문제를 해결하기 위해 만들어졌습니다.</p><h3>추천 네트워크</h3><p>수천 명의 학생들과 여행자들이 우리의 검증된 목록과 신뢰할 수 있는 커뮤니티를 통해 멜버른에서 완벽한 집을 찾았습니다.</p><h3>학생 및 다목적 스포츠 중심</h3><p>우리는 국제 학생들의 필요를 이해합니다 — 대학과의 근접성부터 학기 일정에 맞춘 유연한 임대 계약까지.</p><h3>포괄적인 편안함</h3><p>공과금, Wi-Fi, 청소 서비스, 가구가 모두 포함되어 있습니다. 짐만 챙겨 오시면 됩니다 — 나머지는 저희가 처리합니다.</p>", "cta_title": "최고의 선택", "why_title": "왜 우리를 선택해야 할까요", "cta_button": "방 찾기", "hero_title": "환영합니다", "stat_rooms": "500개 이상", "cta_subtitle": "멜버른의 주요 학생 거주 지역에서 완벽한 방을 찾아보세요. 모든 비용 포함 가격, 유연한 계약, 다국어 지원.", "stat_support": "24/7", "hero_subtitle": "호주 멜버른에서 믿을 수 있는 제2의 집", "feature_1_body": "수천 명의 학생들과 여행자들이 우리의 검증된 목록과 신뢰할 수 있는 커뮤니티를 통해 멜버른에서 완벽한 집을 찾았습니다.", "feature_2_body": "우리는 국제 학생들의 필요를 이해합니다 — 대학과의 근접성부터 학기 일정에 맞춘 유연한 임대 계약까지.", "feature_3_body": "공과금, Wi-Fi, 청소 서비스, 가구가 모두 포함되어 있습니다. 짐만 챙겨 오시면 됩니다 — 나머지는 저희가 처리합니다.", "feature_1_title": "추천 네트워크", "feature_2_title": "학생 및 다목적 스포츠 중심", "feature_3_title": "포괄적인 편안함", "hero_cta_primary": "객실 둘러보기", "stat_universities": "22개 이상", "hero_cta_secondary": "자세히 알아보기"}', 'MillionStay — 멜버른 학생 숙소', '안전하고 저렴하며 완비된 가구가 제공되는 멜버른 학생 숙소를 만나보십시오. 주요 대학 근처에서 1~6개월 유연한 숙박 계획을 제공합니다.', '멜버른 학생 숙소, 국제 학생 주택, 멜버른 가구 완비된 방, 대학 숙소', '2026-04-16 03:00:46.307+00'),
	(1, 'home', 'en', '{"why_body": "<p>We know that finding safe, comfortable, and affordable accommodation in a new country is one of the biggest challenges you''ll face. MillionStay was built to solve exactly that.</p><h3>Testimonials Network</h3><p>Thousands of happy students and nomads have found their perfect Melbourne home through our verified listings and trusted community.</p><h3>Student &amp; Multi-Sport Focus</h3><p>We understand the needs of international students — from university proximity to flexible leases that match your enrollment period.</p><h3>All-Inclusive Comfort</h3><p>Utilities, Wi-Fi, cleaning, and furnishings are all included. Move in with just your luggage — we handle everything else.</p>", "cta_title": "YOUR BEST CHOICE", "why_title": "Why Choose Us", "cta_button": "Find a Room", "hero_title": "WELCOME", "stat_rooms": "500+", "cta_subtitle": "Find your perfect room in Melbourne''s top student suburbs. All-inclusive pricing, flexible contracts, multilingual support.", "stat_support": "24/7", "hero_subtitle": "Your trusted home away from home in Melbourne, Australia", "feature_1_body": "Thousands of happy students and nomads have found their perfect Melbourne home through our verified listings and trusted community.", "feature_2_body": "We understand the needs of international students — from university proximity to flexible leases that match your enrollment period.", "feature_3_body": "Utilities, Wi-Fi, cleaning, and furnishings are all included. Move in with just your luggage — we handle everything else.", "feature_1_title": "Testimonials Network", "feature_2_title": "Student & Multi-Sport Focus", "feature_3_title": "All-Inclusive Comfort", "hero_cta_primary": "Browse Rooms", "stat_universities": "22+", "hero_cta_secondary": "Learn More"}', 'MillionStay — Student Accommodation Melbourne', 'Safe, affordable, fully furnished student accommodation in Melbourne. Flexible 1–6 month stay plans near top universities.', 'student accommodation Melbourne, international student housing, furnished rooms Melbourne, university accommodation', '2026-04-16 03:00:39.146+00'),
	(7, 'faq', 'en', '{"cta_body": "Our team is here to help. Get in touch and we''ll respond within 24 hours.", "cta_title": "Still have questions?", "cta_button": "Contact Us", "hero_title": "Frequently Asked Questions", "hero_subtitle": "Got questions?", "section_1_body": "<h3>How do I book a room at MillionStay?</h3><p>You can browse available rooms on our Location page and submit an enquiry or application directly from each listing. Our team will get back to you within 24 hours to confirm availability and guide you through the next steps.</p><h3>What is included in the rent?</h3><p>All our rooms include Wi-Fi, utilities (electricity, water, gas), weekly cleaning of common areas, and access to shared kitchen and laundry facilities.</p><h3>Can I view the room before booking?</h3><p>Yes! We offer both in-person and virtual tours. For international students arriving from overseas, we can organise a detailed video walkthrough.</p><h3>What is the minimum stay period?</h3><p>Our minimum stay is typically 4 weeks (1 month). We offer flexible monthly rolling contracts with no long-term lease commitment.</p>", "section_2_body": "<h3>Is there a bond or security deposit?</h3><p>Yes, a bond equivalent to 4 weeks'' rent is required upon signing. This is held in accordance with Victorian tenancy law and returned at the end of your stay, provided the room is left in good condition.</p><h3>Are bills included in the weekly price?</h3><p>Yes, electricity, water, gas, and high-speed internet are all included in your weekly rent. There are no hidden costs.</p><h3>How do I pay my rent?</h3><p>Rent is payable weekly or fortnightly via bank transfer or credit card. You will receive an invoice through your online portal each billing cycle.</p>", "section_3_body": "<h3>Do you cater to international students?</h3><p>Absolutely — international students are our core community. We have multilingual staff (Korean, Japanese, Chinese, Thai), and our rooms are designed to make your transition to Melbourne as comfortable as possible.</p><h3>What documents do I need to provide?</h3><p>Typically you will need a copy of your passport, student ID or enrolment letter, and proof of funds. Our team will advise you on exactly what''s needed.</p><h3>Can I have guests stay overnight?</h3><p>Overnight guests are allowed with advance notice to management, up to a maximum of 2 consecutive nights. Extended stays must be approved.</p>", "section_1_title": "Booking & Rooms", "section_2_title": "Payments & Bond", "section_3_title": "Student Support"}', 'FAQ — MillionStay Student Accommodation Melbourne', 'Answers to common questions about booking, payments, bills, bond, and student support at MillionStay Melbourne.', 'MillionStay FAQ, student accommodation questions Melbourne, booking FAQ, rent includes utilities', '2026-04-16 03:00:39.185+00'),
	(8, 'contact', 'en', '{"email": "info@millionstay.com", "hours": "Monday – Friday: 9:00 AM – 6:00 PM\nSaturday: 10:00 AM – 4:00 PM\nSunday: Closed", "phone": "+61 3 9000 0000", "address": "Level 5, 123 Collins Street\nMelbourne VIC 3000\nAustralia", "form_title": "Send us a message", "hero_title": "Contact Us", "email_label": "Email", "hours_label": "Business Hours", "phone_label": "Phone", "address_title": "Office Address", "form_subtitle": "Have a question about our rooms, booking process, or stay plans? Our multilingual team is here to help — in English, Korean, Chinese, Japanese or Thai.", "hero_subtitle": "We''d love to hear from you"}', 'Contact MillionStay — Melbourne Student Accommodation', 'Get in touch with MillionStay. We respond within 24 hours in English, Korean, Chinese, Japanese and Thai.', 'contact MillionStay Melbourne, student accommodation enquiry, multilingual support Melbourne', '2026-04-16 03:00:39.194+00'),
	(9, 'home', 'ja', '{"why_body": "<p>新しい国で安全で快適、かつ手頃な価格の宿泊施設を見つけることは、最も大きな課題の一つです。MillionStayはその課題を解決するために作られました。</p><h3>Testimonials Network</h3><p>何千人もの学生やノマドが、私たちの認証済みリスティングと信頼できるコミュニティを通じて、理想のメルボルンの家を見つけています。</p><h3>学生＆マルチスポーツ重視</h3><p>大学への近さから、入学期間に合わせた柔軟な契約まで、国際学生のニーズを理解しています。</p><h3>オールインクルーシブの快適さ</h3><p>光熱費、Wi-Fi、清掃、家具がすべて含まれています。荷物一つで引っ越し可能 — その他のことはすべてお任せください。</p>", "cta_title": "最良の選択", "why_title": "私たちを選ぶ理由", "cta_button": "部屋を探す", "hero_title": "ようこそ", "stat_rooms": "500以上", "cta_subtitle": "メルボルンの学生に人気のある郊外で理想の部屋を見つけましょう。オールインクルーシブ価格、柔軟な契約、多言語サポート。", "stat_support": "24時間365日", "hero_subtitle": "メルボルン、オーストラリアで信頼できる第二の家", "feature_1_body": "何千人もの学生やノマドが、私たちの認証済みリスティングと信頼できるコミュニティを通じて、理想のメルボルンの家を見つけています。", "feature_2_body": "大学への近さから、入学期間に合わせた柔軟な契約まで、国際学生のニーズを理解しています。", "feature_3_body": "光熱費、Wi-Fi、清掃、家具がすべて含まれています。荷物一つで引っ越し可能 — その他のことはすべてお任せください。", "feature_1_title": "Testimonials Network", "feature_2_title": "学生＆マルチスポーツ重視", "feature_3_title": "オールインクルーシブの快適さ", "hero_cta_primary": "部屋を探す", "stat_universities": "22以上", "hero_cta_secondary": "詳しく見る"}', 'MillionStay — 学生向け宿泊施設 メルボルン', '安全で手頃な価格、完全家具付きの学生向け宿泊施設をメルボルンでご提供します。主要大学の近くで、1〜6か月の柔軟な滞在プランをご利用いただけます。', '学生宿泊施設 メルボルン, 留学生向け住宅, 家具付き部屋 メルボルン, 大学宿泊施設', '2026-04-16 03:00:46.143092+00'),
	(10, 'home', 'vi', '{"why_body": "<p>Chúng tôi hiểu rằng việc tìm kiếm chỗ ở an toàn, thoải mái và hợp túi tiền tại một quốc gia mới là một trong những thách thức lớn nhất mà bạn sẽ phải đối mặt. MillionStay được xây dựng để giải quyết chính vấn đề đó.</p><h3>Mạng Lưới Đánh Giá</h3><p>Hàng ngàn sinh viên và du mục hài lòng đã tìm được ngôi nhà hoàn hảo của mình tại Melbourne thông qua danh sách được xác minh và cộng đồng đáng tin cậy của chúng tôi.</p><h3>Tập Trung Vào Sinh Viên &amp; Thể Thao Đa Dạng</h3><p>Chúng tôi hiểu nhu cầu của sinh viên quốc tế — từ sự gần gũi với trường đại học đến các hợp đồng thuê linh hoạt phù hợp với thời gian học của bạn.</p><h3>Sự Thoải Mái Toàn Diện</h3><p>Tiện ích, Wi-Fi, dọn dẹp và nội thất đều được bao gồm. Chỉ cần mang hành lý của bạn đến — chúng tôi sẽ lo mọi thứ còn lại.</p>", "cta_title": "LỰA CHỌN TỐT NHẤT CỦA BẠN", "why_title": "Tại Sao Chọn Chúng Tôi", "cta_button": "Tìm Phòng", "hero_title": "CHÀO MỪNG", "stat_rooms": "500+", "cta_subtitle": "Tìm phòng hoàn hảo của bạn tại các khu vực sinh viên hàng đầu ở Melbourne. Giá cả trọn gói, hợp đồng linh hoạt, hỗ trợ đa ngôn ngữ.", "stat_support": "24/7", "hero_subtitle": "Ngôi nhà đáng tin cậy của bạn khi xa nhà tại Melbourne, Úc", "feature_1_body": "Hàng ngàn sinh viên và du mục hài lòng đã tìm được ngôi nhà hoàn hảo của mình tại Melbourne thông qua danh sách được xác minh và cộng đồng đáng tin cậy của chúng tôi.", "feature_2_body": "Chúng tôi hiểu nhu cầu của sinh viên quốc tế — từ sự gần gũi với trường đại học đến các hợp đồng thuê linh hoạt phù hợp với thời gian học của bạn.", "feature_3_body": "Tiện ích, Wi-Fi, dọn dẹp và nội thất đều được bao gồm. Chỉ cần mang hành lý của bạn đến — chúng tôi sẽ lo mọi thứ còn lại.", "feature_1_title": "Mạng Lưới Đánh Giá", "feature_2_title": "Tập Trung Vào Sinh Viên & Thể Thao Đa Dạng", "feature_3_title": "Sự Thoải Mái Toàn Diện", "hero_cta_primary": "Xem Phòng", "stat_universities": "22+", "hero_cta_secondary": "Tìm Hiểu Thêm"}', 'MillionStay — Chỗ Ở Cho Sinh Viên Tại Melbourne', 'Chỗ ở an toàn, giá cả phải chăng, đầy đủ tiện nghi dành cho sinh viên tại Melbourne. Các gói lưu trú linh hoạt từ 1–6 tháng gần các trường đại học hàng đầu.', 'chỗ ở cho sinh viên Melbourne, nhà ở cho sinh viên quốc tế, phòng đầy đủ tiện nghi Melbourne, chỗ ở gần trường đại học', '2026-04-16 03:00:49.580108+00'),
	(11, 'home', 'zh', '{"why_body": "<p>我们深知，在一个新国家找到安全、舒适且价格合理的住宿是您面临的最大挑战之一。MillionStay 正是为了解决这一问题而建立的。</p><h3>推荐网络</h3><p>成千上万的学生和旅行者通过我们的经过验证的房源和值得信赖的社区找到了他们在墨尔本的理想家园。</p><h3>学生及多运动项目专注</h3><p>我们了解国际学生的需求——从靠近大学的位置到与您入学期间相匹配的灵活租赁合同。</p><h3>全包式舒适体验</h3><p>水电费、Wi-Fi、清洁服务和家具全都包含在内。您只需带上行李即可入住——其他一切由我们负责。</p>", "cta_title": "您的最佳选择", "why_title": "为什么选择我们", "cta_button": "寻找房间", "hero_title": "欢迎", "stat_rooms": "500+", "cta_subtitle": "在墨尔本顶级学生区找到您的理想房间。全包式定价、灵活合同、多语言支持。", "stat_support": "24/7", "hero_subtitle": "您在澳大利亚墨尔本值得信赖的家外之家", "feature_1_body": "成千上万的学生和旅行者通过我们的经过验证的房源和值得信赖的社区找到了他们在墨尔本的理想家园。", "feature_2_body": "我们了解国际学生的需求——从靠近大学的位置到与您入学期间相匹配的灵活租赁合同。", "feature_3_body": "水电费、Wi-Fi、清洁服务和家具全都包含在内。您只需带上行李即可入住——其他一切由我们负责。", "feature_1_title": "推荐网络", "feature_2_title": "学生及多运动项目专注", "feature_3_title": "全包式舒适体验", "hero_cta_primary": "浏览房间", "stat_universities": "22+", "hero_cta_secondary": "了解更多"}', 'MillionStay — 学生住宿 墨尔本', '安全、实惠、全家具配置的学生住宿，位于墨尔本。提供灵活的1至6个月住宿计划，靠近顶尖大学。', '学生住宿 墨尔本, 国际学生住房, 配家具房间 墨尔本, 大学住宿', '2026-04-16 03:00:53.340615+00'),
	(12, 'for-student', 'zh', '{"hero_title": "为学生服务", "intro_body": "<p>来到一个新的国家令人兴奋——但找到一个安全、实惠的住所不应该成为压力。MillionStay 专注于帮助国际学生在墨尔本找到优质的住宿，整个流程都围绕您的需求设计。</p><p>我们直接与墨尔本的大学、移民代理和学生支持服务合作，确保您的过渡尽可能顺利。从您咨询的那一刻到退房的那一天，我们的多语种团队始终在您身边。</p><p>我们的房间位于墨尔本领先大学附近——University of Melbourne、RMIT、Swinburne、Monash、Deakin 等——这些区域交通便利且社区安全。</p>", "cta_primary": "浏览房间", "intro_title": "您远离家乡的家", "cta_secondary": "发送咨询", "hero_subtitle": "海外学生项目", "feature_1_body": "每间房间在上线前都由我们的团队亲自检查。没有骗局，没有意外。", "feature_2_body": "我们的团队会说英语、韩语、中文、日语和泰语。我们用您的语言为您提供帮助。", "feature_3_body": "住宿时间从4周到24周不等。无需长期租约，无需压力——灵活性与您的学习计划相匹配。", "feature_4_body": "高速 Wi-Fi、电费、水费和燃气费均包含在您的每周费用中。没有意外的账单。", "hero_image_url": "", "feature_1_title": "已验证且安全的房间", "feature_2_title": "多语言支持", "feature_3_title": "灵活的住宿计划", "feature_4_title": "账单全包"}', '墨尔本学生住宿 — MillionStay', '寻找靠近墨尔本顶尖大学的安全且实惠的学生房间。提供灵活的1至6个月租赁计划，包含所有账单，支持多语言服务。', '墨尔本学生住宿, 国际学生房间, 墨尔本大学宿舍, 配家具的学生房间', '2026-04-16 03:01:00.50441+00'),
	(3, 'for-student', 'ko', '{"hero_title": "학생을 위한 서비스", "intro_body": "<p>새로운 나라에 도착하는 것은 흥미로운 일이지만, 안전하고 저렴한 거주지를 찾는 일이 스트레스가 되어서는 안 됩니다. MillionStay는 국제 학생들이 멜버른에서 품질 높은 숙소를 찾을 수 있도록 전문적으로 돕고 있으며, 학생들의 필요에 맞춘 절차를 제공합니다.</p><p>우리는 멜버른 전역의 대학교, 이민 대행사 및 학생 지원 서비스와 직접 협력하여 여러분의 전환 과정을 최대한 원활하게 만들어 드립니다. 문의를 시작하는 순간부터 체크아웃하는 날까지, 다국어를 구사하는 저희 팀이 항상 곁에 있습니다.</p><p>저희 숙소는 멜버른의 주요 대학교 — University of Melbourne, RMIT, Swinburne, Monash, Deakin 등 — 근처의 교통이 편리하고 안전한 교외 지역에 위치해 있습니다.</p>", "cta_primary": "방 둘러보기", "intro_title": "당신의 새로운 집", "cta_secondary": "문의하기", "hero_subtitle": "해외 유학생 프로그램", "feature_1_body": "모든 방은 등록 전에 저희 팀이 직접 점검합니다. 사기나 불쾌한 놀라움은 없습니다.", "feature_2_body": "저희 팀은 영어, 한국어, 중국어, 일본어, 태국어를 구사합니다. 여러분의 언어로 도움을 드립니다.", "feature_3_body": "4주에서 24주까지 숙박 가능합니다. 장기 계약 없이, 학업 일정에 맞춘 유연한 옵션을 제공합니다.", "feature_4_body": "고속 Wi-Fi, 전기, 수도 및 가스 요금이 주간 요금에 포함되어 있습니다. 추가 공과금 걱정은 없습니다.", "hero_image_url": "", "feature_1_title": "검증된 안전한 방", "feature_2_title": "다국어 지원", "feature_3_title": "유연한 숙박 계획", "feature_4_title": "청구서 포함"}', 'Student Accommodation Melbourne — MillionStay', '멜버른 주요 대학교 근처에서 안전하고 저렴한 학생 숙소를 찾아보세요. 유연한 1–6개월 플랜, 모든 요금 포함, 다국어 지원을 제공합니다.', '멜버른 학생 숙소, 국제 학생을 위한 방, 멜버른 대학교 주택, 가구가 갖춰진 학생 방', '2026-04-16 03:01:04.176+00'),
	(13, 'for-student', 'ja', '{"hero_title": "学生向け", "intro_body": "<p>新しい国に到着することはワクワクしますが、安全で手頃な住まいを見つけることがストレスになるべきではありません。MillionStayは、メルボルンで質の高い宿泊施設を探す国際学生を支援することを専門としています。私たちのプロセスは、あなたのニーズに合わせて設計されています。</p><p>私たちは、メルボルン中の大学、移民エージェント、学生支援サービスと直接連携し、あなたの移行を可能な限りスムーズにします。お問い合わせいただいた瞬間からチェックアウトの日まで、私たちの多言語チームがあなたのそばにいます。</p><p>私たちの部屋は、University of Melbourne、RMIT、Swinburne、Monash、Deakinなど、メルボルンの主要大学の近くに位置しており、交通の便が良く、安全な郊外の地域にあります。</p>", "cta_primary": "部屋を見る", "intro_title": "第二の故郷", "cta_secondary": "お問い合わせを送信", "hero_subtitle": "海外留学生プログラム", "feature_1_body": "すべての部屋は掲載前に私たちのチームが直接検査しています。詐欺や驚きはありません。", "feature_2_body": "私たちのチームは英語、韓国語、中国語、日本語、タイ語を話します。あなたの言語でお手伝いします。", "feature_3_body": "4週間から24週間まで滞在可能です。長期契約なし、ストレスなし — あなたの学習スケジュールに合わせた柔軟性を提供します。", "feature_4_body": "高速Wi-Fi、電気、水道、ガスが週料金に含まれています。予想外の光熱費はありません。", "hero_image_url": "", "feature_1_title": "検証済みで安全な部屋", "feature_2_title": "多言語サポート", "feature_3_title": "柔軟な滞在プラン", "feature_4_title": "料金に含まれる光熱費"}', 'Student Accommodation Melbourne — MillionStay', 'メルボルンの主要大学の近くで安全で手頃な学生向けのお部屋を見つけましょう。1〜6か月の柔軟なプラン、すべての料金込み、多言語サポートをご利用いただけます。', '学生宿泊施設 メルボルン, 留学生向け部屋, 大学住宅 メルボルン, 家具付き学生部屋', '2026-04-16 03:01:04.393182+00'),
	(14, 'for-student', 'vi', '{"hero_title": "Dành Cho Sinh Viên", "intro_body": "<p>Đến một đất nước mới thật thú vị — nhưng việc tìm một nơi ở an toàn, giá cả phải chăng không nên là điều căng thẳng. MillionStay chuyên hỗ trợ sinh viên quốc tế tìm chỗ ở chất lượng tại Melbourne, với quy trình được thiết kế xoay quanh nhu cầu của bạn.</p><p>Chúng tôi làm việc trực tiếp với các trường đại học, đại lý di trú và dịch vụ hỗ trợ sinh viên trên khắp Melbourne để giúp bạn chuyển tiếp một cách suôn sẻ nhất có thể. Từ lúc bạn gửi yêu cầu đến ngày bạn trả phòng, đội ngũ đa ngôn ngữ của chúng tôi luôn đồng hành cùng bạn.</p><p>Các phòng của chúng tôi nằm gần các trường đại học hàng đầu tại Melbourne — University of Melbourne, RMIT, Swinburne, Monash, Deakin và nhiều trường khác — trong các khu dân cư an toàn, thuận tiện giao thông.</p>", "cta_primary": "Xem Phòng", "intro_title": "NGÔI NHÀ CỦA BẠN KHI XA NHÀ", "cta_secondary": "Gửi Yêu Cầu", "hero_subtitle": "Chương Trình Sinh Viên Quốc Tế", "feature_1_body": "Mỗi phòng đều được đội ngũ của chúng tôi kiểm tra trực tiếp trước khi niêm yết. Không lừa đảo, không bất ngờ.", "feature_2_body": "Đội ngũ của chúng tôi nói tiếng Anh, tiếng Hàn, tiếng Trung, tiếng Nhật và tiếng Thái. Chúng tôi sẵn sàng hỗ trợ bạn bằng ngôn ngữ của bạn.", "feature_3_body": "Lưu trú từ 4 đến 24 tuần. Không hợp đồng dài hạn, không căng thẳng — chỉ sự linh hoạt phù hợp với lịch học của bạn.", "feature_4_body": "Wi-Fi tốc độ cao, điện, nước và gas đều được bao gồm trong giá thuê hàng tuần của bạn. Không có hóa đơn tiện ích bất ngờ.", "hero_image_url": "", "feature_1_title": "Phòng Được Xác Minh & An Toàn", "feature_2_title": "Hỗ Trợ Đa Ngôn Ngữ", "feature_3_title": "Kế Hoạch Lưu Trú Linh Hoạt", "feature_4_title": "Bao Gồm Hóa Đơn"}', 'Chỗ Ở Cho Sinh Viên Tại Melbourne — MillionStay', 'Tìm kiếm phòng ở an toàn, giá cả phải chăng gần các trường đại học hàng đầu tại Melbourne. Kế hoạch linh hoạt từ 1–6 tháng, bao gồm tất cả hóa đơn, hỗ trợ đa ngôn ngữ.', 'chỗ ở cho sinh viên Melbourne, phòng cho sinh viên quốc tế, nhà ở đại học Melbourne, phòng ở sinh viên đầy đủ tiện nghi', '2026-04-16 03:01:05.247475+00'),
	(15, 'for-agent', 'zh', '{"how_body": "<h3>01 — 提交合作申请</h3><p>填写我们的代理注册表。我们将在两个工作日内审核您的申请并回复。</p><h3>02 — 审核通过并完成入驻</h3><p>审核通过后，您将获得访问我们的代理门户、房源库存以及联合品牌材料的权限。</p><h3>03 — 推荐客户并赚取佣金</h3><p>向MillionStay推荐客户并跟踪每次预订。佣金将在成功入住后及时支付。</p>", "cta_title": "代理注册", "how_title": "如何加入", "cta_button": "申请合作", "hero_title": "代理合作", "intro_body": "<p>您是移民代理、教育顾问或学生招募机构吗？MillionStay诚邀您加入我们不断壮大的合作伙伴网络，通过为您的客户推荐墨尔本优质住宿赚取佣金。</p><p>我们了解国际学生在搬迁到墨尔本时面临的挑战。我们的认证房源、多语言团队以及无缝的预订流程，使我们成为墨尔本学生住宿领域最值得信赖的推荐合作伙伴。</p><p>无论您的客户来自韩国、中国、日本、泰国、印度或其他国家，MillionStay都能为每位客户提供合适的住宿和支持。</p>", "intro_title": "与MillionStay合作", "hero_subtitle": "合作伙伴计划", "benefit_1_body": "每次成功预订均可赚取行业领先的推荐佣金。佣金将在客人入住后及时支付。", "benefit_2_body": "接触覆盖韩国、中国、日本、泰国及其他国家的广泛国际学生市场。", "benefit_3_body": "通过专属代理门户跟踪您的推荐、佣金和预订状态。", "benefit_1_title": "具有竞争力的佣金", "benefit_2_title": "多语言客户群", "benefit_3_title": "实时管理平台"}', '代理合作计划 — MillionStay Melbourne', '加入MillionStay的代理合作网络。通过推荐国际学生入住墨尔本顶级学生住宿，赚取具有竞争力的佣金。', '移民代理 墨尔本, 学生住宿推荐, 代理合作计划, 墨尔本住宿佣金', '2026-04-16 03:01:14.28384+00'),
	(16, 'for-agent', 'ja', '{"how_body": "<h3>01 — パートナー申請</h3><p>エージェント登録フォームにご記入ください。申請内容を確認し、2営業日以内にご連絡いたします。</p><h3>02 — 承認とオンボーディング</h3><p>承認後、エージェントポータル、物件情報、共同ブランド資料へのアクセスが提供されます。</p><h3>03 — 紹介して収益を得る</h3><p>MillionStayにお客様を紹介し、すべての予約を追跡します。コミッションは成功したチェックイン後に迅速にお支払いします。</p>", "cta_title": "エージェント登録", "how_title": "参加方法", "cta_button": "パートナー申請", "hero_title": "エージェント向け", "intro_body": "<p>移民エージェント、教育コンサルタント、または学生募集エージェンシーの方ですか？MillionStayでは、私たちの成長するパートナーネットワークに参加し、プレミアムなメルボルンの宿泊施設をお客様に紹介することでコミッションを獲得する機会を提供しています。</p><p>私たちは、メルボルンに移住する際に国際学生が直面する課題を理解しています。MillionStayの認定物件、多言語対応のチーム、そしてスムーズな予約プロセスにより、私たちはメルボルンで最も信頼される学生住宅の紹介パートナーとなっています。</p><p>韓国、中国、日本、タイ、インド、その他の国の学生を対象にしている場合でも、MillionStayはすべてのお客様のニーズに合った宿泊施設とサポートを提供します。</p>", "intro_title": "MILLIONSTAYとの提携", "hero_subtitle": "パートナープログラム", "benefit_1_body": "成功した予約ごとに業界トップクラスの紹介コミッションを獲得できます。ゲストのチェックイン後、迅速にお支払いします。", "benefit_2_body": "韓国、中国、日本、タイなど、幅広い国際学生市場にアクセスできます。", "benefit_3_body": "専用のエージェントポータルを通じて、紹介、コミッション、予約状況を追跡できます。", "benefit_1_title": "競争力のあるコミッション", "benefit_2_title": "多言語対応の顧客", "benefit_3_title": "リアルタイムダッシュボード"}', 'エージェントパートナープログラム — MillionStay Melbourne', 'MillionStayのエージェントパートナーネットワークにご参加ください。メルボルンのトップ学生宿泊施設を国際学生に紹介して、競争力のあるコミッションを獲得しましょう。', '移民エージェント メルボルン, 学生宿泊施設 紹介, エージェントパートナープログラム, 宿泊施設 コミッション メルボルン', '2026-04-16 03:01:15.591509+00'),
	(17, 'for-agent', 'vi', '{"how_body": "<h3>01 — Đăng Ký Làm Đối Tác</h3><p>Hoàn thành biểu mẫu đăng ký đại lý của chúng tôi. Chúng tôi sẽ xem xét đơn của bạn và phản hồi trong vòng 2 ngày làm việc.</p><h3>02 — Được Phê Duyệt &amp; Hướng Dẫn</h3><p>Sau khi được phê duyệt, bạn sẽ nhận được quyền truy cập vào cổng thông tin đại lý, danh mục bất động sản và tài liệu đồng thương hiệu.</p><h3>03 — Giới Thiệu &amp; Kiếm Hoa Hồng</h3><p>Giới thiệu khách hàng đến MillionStay và theo dõi mọi lượt đặt chỗ. Hoa hồng sẽ được thanh toán nhanh chóng sau khi khách hàng check-in thành công.</p>", "cta_title": "ĐĂNG KÝ ĐẠI LÝ", "how_title": "CÁCH THAM GIA", "cta_button": "Đăng Ký Làm Đối Tác", "hero_title": "Dành Cho Đại Lý", "intro_body": "<p>Bạn là đại lý di trú, tư vấn giáo dục hay công ty tuyển sinh? MillionStay mời bạn tham gia vào mạng lưới đối tác đang phát triển của chúng tôi và kiếm hoa hồng bằng cách kết nối khách hàng của bạn với chỗ ở cao cấp tại Melbourne.</p><p>Chúng tôi hiểu những thách thức mà sinh viên quốc tế gặp phải khi chuyển đến Melbourne. Các bất động sản đã được xác minh, đội ngũ đa ngôn ngữ và quy trình đặt chỗ liền mạch của chúng tôi khiến MillionStay trở thành đối tác giới thiệu đáng tin cậy nhất cho nhà ở sinh viên trong thành phố.</p><p>Dù bạn làm việc với sinh viên từ Hàn Quốc, Trung Quốc, Nhật Bản, Thái Lan, Ấn Độ hay các quốc gia khác — MillionStay đều có chỗ ở phù hợp và hỗ trợ đúng nhu cầu cho từng hồ sơ khách hàng.</p>", "intro_title": "HỢP TÁC VỚI MILLIONSTAY", "hero_subtitle": "Chương Trình Đối Tác", "benefit_1_body": "Kiếm hoa hồng giới thiệu hàng đầu trong ngành cho mỗi lần đặt chỗ thành công. Thanh toán nhanh chóng sau khi khách hàng check-in.", "benefit_2_body": "Tiếp cận thị trường sinh viên quốc tế rộng lớn từ Hàn Quốc, Trung Quốc, Nhật Bản, Thái Lan và nhiều quốc gia khác.", "benefit_3_body": "Theo dõi các lượt giới thiệu, hoa hồng và trạng thái đặt chỗ thông qua cổng thông tin dành riêng cho đại lý của chúng tôi.", "benefit_1_title": "Hoa Hồng Cạnh Tranh", "benefit_2_title": "Khách Hàng Đa Ngôn Ngữ", "benefit_3_title": "Bảng Điều Khiển Theo Thời Gian Thực"}', 'Chương Trình Đối Tác Đại Lý — MillionStay Melbourne', 'Tham gia mạng lưới đối tác đại lý của MillionStay. Kiếm hoa hồng cạnh tranh khi giới thiệu sinh viên quốc tế đến các chỗ ở hàng đầu dành cho sinh viên tại Melbourne.', 'đại lý di trú Melbourne, giới thiệu chỗ ở cho sinh viên, chương trình đối tác đại lý, hoa hồng chỗ ở Melbourne', '2026-04-16 03:01:15.603831+00'),
	(18, 'for-agent', 'ko', '{"how_body": "<h3>01 — 파트너 신청</h3><p>에이전트 등록 양식을 작성하세요. 신청서를 검토한 후 영업일 기준 2일 이내에 답변 드리겠습니다.</p><h3>02 — 승인 및 온보딩</h3><p>승인 후, 에이전트 포털, 숙소 목록 및 공동 브랜드 자료에 접근할 수 있습니다.</p><h3>03 — 추천 및 수익</h3><p>MillionStay에 고객을 추천하고 모든 예약을 추적하세요. 성공적인 체크인 후 커미션이 신속히 지급됩니다.</p>", "cta_title": "에이전트 등록", "how_title": "가입 방법", "cta_button": "파트너 신청하기", "hero_title": "에이전트를 위한 프로그램", "intro_body": "<p>귀하가 이민 에이전트, 교육 컨설턴트 또는 학생 모집 에이전시라면, MillionStay는 귀하를 우리의 성장하는 파트너 네트워크에 초대합니다. 고객을 멜버른의 프리미엄 숙소와 연결하여 커미션을 획득하세요.</p><p>우리는 국제 학생들이 멜버른으로 이주할 때 직면하는 어려움을 잘 이해하고 있습니다. 검증된 숙소, 다국어를 구사하는 팀, 그리고 원활한 예약 프로세스를 통해 우리는 멜버른에서 가장 신뢰받는 학생 주택 추천 파트너로 자리 잡았습니다.</p><p>한국, 중국, 일본, 태국, 인도 등 다양한 국가의 학생들과 함께 일하든지 간에, MillionStay는 모든 고객 프로필에 적합한 숙소와 지원을 제공합니다.</p>", "intro_title": "MILLIONSTAY와 파트너가 되세요", "hero_subtitle": "파트너 프로그램", "benefit_1_body": "성공적인 예약마다 업계 최고 수준의 추천 커미션을 획득하세요. 고객 체크인 후 신속히 지급됩니다.", "benefit_2_body": "한국, 중국, 일본, 태국 등 다양한 국제 학생 시장에 접근할 수 있습니다.", "benefit_3_body": "전용 에이전트 포털을 통해 추천, 커미션 및 예약 상태를 추적하세요.", "benefit_1_title": "경쟁력 있는 커미션", "benefit_2_title": "다국어 고객 지원", "benefit_3_title": "실시간 대시보드"}', 'Agent Partner Program — MillionStay Melbourne', 'MillionStay의 에이전트 파트너 네트워크에 가입하십시오. 멜버른 최고의 학생 숙소를 국제 학생들에게 추천하여 경쟁력 있는 수수료를 받으실 수 있습니다.', '이민 에이전트 멜버른, 학생 숙소 추천, 에이전트 파트너 프로그램, 숙소 수수료 멜버른', '2026-04-16 03:01:15.868725+00'),
	(19, 'about', 'zh', '{"team_body": "<p>我们的小型但敬业的团队汇集了物业管理、学生服务和国际关系方面的专业知识。</p><p><strong>Sarah Johnson</strong> — 创始人兼首席执行官。Sarah于2015年创立MillionStay，旨在改变墨尔本的学生住宿模式。</p><p><strong>David Kim</strong> — 运营经理。David负责管理我们的房产网络，并确保每个房间都符合我们的严格质量标准。</p><p><strong>Mia Chen</strong> — 学生关系负责人。Mia用英语、中文和韩语为我们的国际学生提供从咨询到退房的全程支持。</p>", "hero_title": "关于我们", "team_title": "我们的团队", "mission_body": "<p>MillionStay成立的使命很简单：让墨尔本的住宿真正对国际学生和数字游民开放并充满欢迎。我们知道，在一个新的国家找到一个安全、舒适且价格合理的家是您面临的最大挑战之一——而我们在这里帮助您轻松应对。</p><p>我们的多语言团队（英语、韩语、中文、日语和泰语）每天都在努力为学生匹配合适的房间，处理相关文件，并确保每位客人从抵达的那一刻起就感到宾至如归。</p><p>我们提供灵活的住宿计划，时间从1个月到6个月不等，经过质量验证的房间遍布墨尔本最适合学生居住的区域，并在您整个住宿期间提供个性化支持。没有隐藏费用，没有压力——只是一个可以称之为家的好地方。</p>", "value_1_body": "我们相信每个人都应享有安全、实惠的住宿——无论他们的背景或语言如何。", "value_2_body": "我们列出的每一处房产都经过团队的亲自验证。您看到的就是您得到的。", "value_3_body": "我们与租客建立持久的关系，在他们整个墨尔本旅程中提供支持。", "values_title": "我们的价值观", "hero_subtitle": "我们的身份", "mission_title": "了解我们", "value_1_title": "可及性", "value_2_title": "信任", "value_3_title": "社区"}', '关于 MillionStay — 墨尔本学生住宿', '了解 MillionStay — 自2015年以来致力于在墨尔本提供安全、实惠、多语言的学生住宿。', '关于 MillionStay, 墨尔本学生住宿公司, 多语言物业管理', '2026-04-16 03:01:22.294519+00'),
	(20, 'about', 'vi', '{"team_body": "<p>Đội ngũ nhỏ nhưng tận tâm của chúng tôi kết hợp chuyên môn về quản lý bất động sản, dịch vụ sinh viên và quan hệ quốc tế.</p><p><strong>Sarah Johnson</strong> — Người Sáng Lập &amp; CEO. Sarah thành lập MillionStay vào năm 2015 với tầm nhìn thay đổi cách thức cung cấp chỗ ở cho sinh viên tại Melbourne.</p><p><strong>David Kim</strong> — Quản Lý Vận Hành. David giám sát mạng lưới bất động sản của chúng tôi và đảm bảo mọi phòng đều đáp ứng các tiêu chuẩn chất lượng nghiêm ngặt.</p><p><strong>Mia Chen</strong> — Quan Hệ Sinh Viên. Mia hỗ trợ các sinh viên quốc tế của chúng tôi từ lúc gửi yêu cầu đến lúc trả phòng, bằng Tiếng Anh, Tiếng Trung và Tiếng Hàn.</p>", "hero_title": "Về Chúng Tôi", "team_title": "Đội Ngũ Của Chúng Tôi", "mission_body": "<p>MillionStay được thành lập với một sứ mệnh đơn giản: làm cho việc tìm kiếm chỗ ở tại Melbourne trở nên dễ dàng và thân thiện hơn đối với sinh viên quốc tế và những người làm việc từ xa. Chúng tôi hiểu rằng việc tìm một nơi ở an toàn, thoải mái và hợp túi tiền tại một quốc gia mới là một trong những thử thách lớn nhất mà bạn sẽ phải đối mặt — và chúng tôi ở đây để giúp bạn vượt qua điều đó.</p><p>Đội ngũ đa ngôn ngữ của chúng tôi (Tiếng Anh, Tiếng Hàn, Tiếng Trung, Tiếng Nhật và Tiếng Thái) làm việc mỗi ngày để kết nối sinh viên với các phòng phù hợp, xử lý giấy tờ và đảm bảo mọi khách hàng đều cảm thấy như ở nhà ngay từ lúc họ đến.</p><p>Chúng tôi cung cấp các kế hoạch lưu trú linh hoạt từ 1 đến 6 tháng, các phòng đã được kiểm định chất lượng tại những khu vực tốt nhất dành cho sinh viên ở Melbourne, và hỗ trợ cá nhân trong suốt thời gian bạn lưu trú. Không có phí ẩn, không căng thẳng — chỉ là một nơi tuyệt vời để gọi là nhà.</p>", "value_1_body": "Chúng tôi tin rằng mọi người đều xứng đáng có chỗ ở an toàn, hợp túi tiền — bất kể xuất thân hay ngôn ngữ của họ.", "value_2_body": "Mỗi bất động sản chúng tôi liệt kê đều được đội ngũ của chúng tôi kiểm định trực tiếp. Những gì bạn thấy là những gì bạn nhận được.", "value_3_body": "Chúng tôi xây dựng mối quan hệ bền vững với các khách thuê, hỗ trợ họ trong suốt hành trình tại Melbourne.", "values_title": "Giá Trị Cốt Lõi", "hero_subtitle": "Chúng tôi là ai", "mission_title": "TÌM HIỂU VỀ CHÚNG TÔI", "value_1_title": "Khả Năng Tiếp Cận", "value_2_title": "Niềm Tin", "value_3_title": "Cộng Đồng"}', 'Về MillionStay — Chỗ Ở Cho Sinh Viên Tại Melbourne', 'Tìm hiểu về MillionStay — được thành lập để cung cấp chỗ ở an toàn, giá cả phải chăng, đa ngôn ngữ cho sinh viên tại Melbourne từ năm 2015.', 'về MillionStay, công ty chỗ ở cho sinh viên Melbourne, quản lý tài sản đa ngôn ngữ', '2026-04-16 03:01:23.128474+00'),
	(21, 'about', 'ko', '{"team_body": "<p>우리의 작지만 헌신적인 팀은 부동산 관리, 학생 서비스 및 국제 관계에 대한 전문성을 결합하고 있습니다.</p><p><strong>Sarah Johnson</strong> — 설립자 &amp; CEO. Sarah는 2015년에 멜버른의 학생 숙소를 혁신하겠다는 비전으로 MillionStay를 설립했습니다.</p><p><strong>David Kim</strong> — 운영 관리자. David는 우리의 부동산 네트워크를 관리하며 모든 방이 엄격한 품질 기준을 충족하도록 보장합니다.</p><p><strong>Mia Chen</strong> — 학생 관계 담당. Mia는 영어, 중국어, 한국어로 국제 학생들을 문의부터 체크아웃까지 지원합니다.</p>", "hero_title": "회사 소개", "team_title": "우리 팀", "mission_body": "<p>MillionStay는 단순한 목표를 가지고 설립되었습니다: 멜버른에서 국제 학생들과 디지털 노마드들이 진정으로 접근 가능하고 환영받는 숙소를 찾을 수 있도록 돕는 것입니다. 새로운 나라에서 안전하고 편안하며 합리적인 가격의 집을 찾는 것은 가장 큰 도전 중 하나라는 것을 우리는 잘 알고 있습니다 — 그래서 이를 더 쉽게 만들어 드리고자 합니다.</p><p>우리의 다국어 팀(영어, 한국어, 중국어, 일본어, 태국어)은 매일 학생들에게 적합한 방을 연결하고, 서류 작업을 처리하며, 도착 순간부터 모든 손님이 집처럼 편안함을 느낄 수 있도록 노력하고 있습니다.</p><p>우리는 1개월에서 6개월까지의 유연한 숙박 계획, 멜버른의 최고의 학생 지역에 위치한 품질 검증된 방, 그리고 숙박 기간 내내 개인적인 지원을 제공합니다. 숨겨진 비용도 없고, 스트레스도 없습니다 — 단지 집이라 부를 수 있는 훌륭한 공간만 있습니다.</p>", "value_1_body": "우리는 모든 사람이 배경이나 언어와 상관없이 안전하고 합리적인 가격의 숙소를 가질 자격이 있다고 믿습니다.", "value_2_body": "우리가 등록한 모든 숙소는 팀이 직접 검증합니다. 보이는 그대로를 제공받으실 수 있습니다.", "value_3_body": "우리는 세입자들과 지속적인 관계를 구축하며, 그들의 멜버른 여정 전반에 걸쳐 지원합니다.", "values_title": "우리의 가치", "hero_subtitle": "우리는 누구인가", "mission_title": "우리를 알아보세요", "value_1_title": "접근성", "value_2_title": "신뢰", "value_3_title": "커뮤니티"}', 'MillionStay 소개 — 멜버른 학생 숙소', 'MillionStay에 대해 알아보십시오 — 2015년부터 멜버른 전역에 안전하고 저렴하며 다국어를 지원하는 학생 숙소를 제공하기 위해 설립되었습니다.', 'MillionStay 소개, 멜버른 학생 숙소 회사, 다국어 부동산 관리', '2026-04-16 03:01:23.215412+00'),
	(22, 'about', 'ja', '{"team_body": "<p>私たちの小規模ながら献身的なチームは、不動産管理、学生サービス、国際関係の専門知識を結集しています。</p><p><strong>Sarah Johnson</strong> — 創設者兼CEO。Sarahは2015年にMillionStayを設立し、メルボルンの学生宿泊施設を変革するというビジョンを持っています。</p><p><strong>David Kim</strong> — オペレーションマネージャー。Davidは物件ネットワークを管理し、すべての部屋が厳格な品質基準を満たしていることを確認しています。</p><p><strong>Mia Chen</strong> — 学生関係担当。Miaは英語、中国語、韓国語で、問い合わせからチェックアウトまで国際学生をサポートしています。</p>", "hero_title": "私たちについて", "team_title": "私たちのチーム", "mission_body": "<p>MillionStayは、メルボルンでの宿泊を国際学生やデジタルノマドにとって本当にアクセスしやすく、歓迎されるものにするというシンプルな使命のもと設立されました。新しい国で安全で快適、かつ手頃な価格の住まいを見つけることは、あなたが直面する最大の課題の1つであり、私たちはそれを簡単にするためにここにいます。</p><p>私たちの多言語対応チーム（英語、韓国語、中国語、日本語、タイ語）は、毎日学生に適した部屋をマッチングし、書類作業を処理し、到着した瞬間からすべてのゲストが自宅のように感じられるよう努めています。</p><p>1ヶ月から6ヶ月までの柔軟な滞在プラン、メルボルンの学生に人気のある地域にある品質保証済みの部屋、そして滞在期間全体を通じて個別のサポートを提供しています。隠れた料金やストレスはありません—ただ素晴らしい住まいを提供します。</p>", "value_1_body": "私たちは、背景や言語に関係なく、誰もが安全で手頃な価格の宿泊施設を利用できるべきだと信じています。", "value_2_body": "私たちが掲載するすべての物件は、チームによって個別に確認されています。掲載内容は実際の物件そのものです。", "value_3_body": "私たちは入居者との長期的な関係を築き、メルボルンでの旅全体を通じてサポートします。", "values_title": "私たちの価値観", "hero_subtitle": "私たちは誰か", "mission_title": "私たちを知る", "value_1_title": "アクセスのしやすさ", "value_2_title": "信頼", "value_3_title": "コミュニティ"}', 'MillionStayについて — メルボルンの学生向け宿泊施設', 'MillionStayについてご紹介します。2015年に設立され、安全で手頃な価格、多言語対応の学生向け宿泊施設をメルボルン全域で提供しています。', 'MillionStayについて, メルボルンの学生向け宿泊施設会社, 多言語対応の物件管理', '2026-04-16 03:01:26.269743+00'),
	(23, 'faq', 'ko', '{"cta_body": "저희 팀이 도와드리겠습니다. 문의하시면 24시간 이내에 답변드리겠습니다.", "cta_title": "아직 궁금한 점이 있으신가요?", "cta_button": "문의하기", "hero_title": "자주 묻는 질문", "hero_subtitle": "궁금한 점이 있으신가요?", "section_1_body": "<h3>MillionStay에서 객실을 예약하려면 어떻게 해야 하나요?</h3><p>Location 페이지에서 이용 가능한 객실을 검색하고 각 목록에서 문의 또는 신청서를 제출하실 수 있습니다. 저희 팀이 24시간 이내에 이용 가능 여부를 확인하고 다음 단계에 대해 안내해 드립니다.</p><h3>임대료에 포함된 항목은 무엇인가요?</h3><p>모든 객실에는 Wi-Fi, 공과금(전기, 물, 가스), 공용 공간의 주간 청소, 공용 주방 및 세탁 시설 이용이 포함됩니다.</p><h3>예약 전에 객실을 볼 수 있나요?</h3><p>네! 대면 투어와 가상 투어를 모두 제공합니다. 해외에서 도착하는 국제 학생들을 위해 상세한 비디오 투어를 준비할 수 있습니다.</p><h3>최소 숙박 기간은 얼마인가요?</h3><p>최소 숙박 기간은 일반적으로 4주(1개월)입니다. 장기 임대 계약 없이 유연한 월별 계약을 제공합니다.</p>", "section_2_body": "<h3>보증금 또는 보안 예치금이 있나요?</h3><p>네, 계약 시 4주 임대료에 해당하는 보증금이 필요합니다. 이는 빅토리아 주 임대법에 따라 보관되며, 객실이 좋은 상태로 유지된 경우 숙박 종료 시 반환됩니다.</p><h3>주간 가격에 청구서가 포함되나요?</h3><p>네, 전기, 물, 가스, 고속 인터넷이 주간 임대료에 모두 포함됩니다. 숨겨진 비용은 없습니다.</p><h3>임대료는 어떻게 지불하나요?</h3><p>임대료는 은행 송금 또는 신용카드를 통해 주간 또는 격주로 지불할 수 있습니다. 각 청구 주기에 온라인 포털을 통해 송장을 받으실 수 있습니다.</p>", "section_3_body": "<h3>국제 학생을 위한 서비스를 제공하나요?</h3><p>물론입니다 — 국제 학생들이 저희의 핵심 커뮤니티입니다. 저희는 다국어를 구사하는 직원들(한국어, 일본어, 중국어, 태국어)을 보유하고 있으며, 멜버른으로의 적응을 최대한 편안하게 할 수 있도록 객실을 설계했습니다.</p><h3>제출해야 할 서류는 무엇인가요?</h3><p>일반적으로 여권 사본, 학생증 또는 등록 확인서, 재정 증명서를 제출해야 합니다. 필요한 서류에 대해 저희 팀이 정확히 안내해 드릴 것입니다.</p><h3>손님이 밤에 머무를 수 있나요?</h3><p>밤에 머무는 손님은 관리팀에 사전 통보한 경우 최대 2박까지 허용됩니다. 장기 체류는 승인이 필요합니다.</p>", "section_1_title": "예약 및 객실", "section_2_title": "결제 및 보증금", "section_3_title": "학생 지원"}', 'FAQ — MillionStay 학생 숙소 멜버른', 'MillionStay 멜버른에서의 예약, 결제, 청구서, 보증금 및 학생 지원에 관한 일반적인 질문에 대한 답변을 제공합니다.', 'MillionStay FAQ, 학생 숙소 질문 멜버른, 예약 FAQ, 임대료에 포함된 공과금', '2026-04-16 03:01:33.316043+00'),
	(24, 'faq', 'zh', '{"cta_body": "我们的团队随时为您提供帮助。联系我们，我们将在24小时内回复。", "cta_title": "还有疑问吗？", "cta_button": "联系我们", "hero_title": "常见问题解答", "hero_subtitle": "有疑问吗？", "section_1_body": "<h3>如何在MillionStay预订房间？</h3><p>您可以在我们的Location页面浏览可用房间，并直接从每个房源提交咨询或申请。我们的团队将在24小时内回复您，确认房间可用性并指导您完成下一步操作。</p><h3>租金包含哪些内容？</h3><p>我们所有的房间均包含Wi-Fi、公共事业费用（电、水、燃气）、公共区域每周清洁服务，以及共享厨房和洗衣设施的使用权限。</p><h3>可以在预订前参观房间吗？</h3><p>可以！我们提供现场参观和虚拟导览服务。对于从海外抵达的国际学生，我们可以安排详细的视频导览。</p><h3>最低入住期限是多少？</h3><p>我们的最低入住期限通常为4周（1个月）。我们提供灵活的每月滚动合同，无需长期租赁承诺。</p>", "section_2_body": "<h3>是否需要缴纳押金或保证金？</h3><p>是的，签署合同时需要缴纳相当于4周租金的押金。这将根据维多利亚州租赁法律进行保管，并在您退房时归还，前提是房间保持良好状态。</p><h3>每周租金是否包含账单费用？</h3><p>是的，电费、水费、燃气费和高速互联网费用均包含在您的每周租金中，没有任何隐藏费用。</p><h3>如何支付租金？</h3><p>租金可以通过银行转账或信用卡按周或每两周支付。您将在每个账单周期通过在线门户收到发票。</p>", "section_3_body": "<h3>是否为国际学生提供服务？</h3><p>当然——国际学生是我们的核心群体。我们拥有会说多种语言的员工（韩语、日语、中文、泰语），我们的房间设计旨在让您在墨尔本的过渡尽可能舒适。</p><h3>我需要提供哪些文件？</h3><p>通常您需要提供护照副本、学生证或入学通知书，以及资金证明。我们的团队会具体告知您需要准备哪些文件。</p><h3>可以让客人过夜吗？</h3><p>允许客人过夜，但需提前通知管理部门，最多连续2晚。延长住宿需获得批准。</p>", "section_1_title": "预订与房间", "section_2_title": "支付与押金", "section_3_title": "学生支持"}', '常见问题 — MillionStay 学生住宿墨尔本', '关于在 MillionStay 墨尔本预订、付款、账单、押金以及学生支持的常见问题解答。', 'MillionStay 常见问题, 墨尔本学生住宿问题, 预订常见问题, 租金包含水电费', '2026-04-16 03:01:34.384436+00'),
	(25, 'faq', 'vi', '{"cta_body": "Đội ngũ của chúng tôi luôn sẵn sàng hỗ trợ. Liên hệ với chúng tôi và chúng tôi sẽ phản hồi trong vòng 24 giờ.", "cta_title": "Vẫn còn thắc mắc?", "cta_button": "Liên Hệ", "hero_title": "Các Câu Hỏi Thường Gặp", "hero_subtitle": "Bạn có thắc mắc?", "section_1_body": "<h3>Làm thế nào để tôi đặt phòng tại MillionStay?</h3><p>Bạn có thể duyệt qua các phòng có sẵn trên trang Location của chúng tôi và gửi yêu cầu hoặc đơn đăng ký trực tiếp từ mỗi danh sách. Đội ngũ của chúng tôi sẽ liên hệ lại với bạn trong vòng 24 giờ để xác nhận tình trạng phòng và hướng dẫn các bước tiếp theo.</p><h3>Tiền thuê bao gồm những gì?</h3><p>Tất cả các phòng của chúng tôi bao gồm Wi-Fi, các tiện ích (điện, nước, gas), dọn dẹp khu vực chung hàng tuần, và quyền sử dụng nhà bếp và giặt là chung.</p><h3>Tôi có thể xem phòng trước khi đặt không?</h3><p>Được! Chúng tôi cung cấp cả các buổi tham quan trực tiếp và trực tuyến. Đối với sinh viên quốc tế đến từ nước ngoài, chúng tôi có thể tổ chức một buổi tham quan chi tiết qua video.</p><h3>Thời gian lưu trú tối thiểu là bao lâu?</h3><p>Thời gian lưu trú tối thiểu của chúng tôi thường là 4 tuần (1 tháng). Chúng tôi cung cấp các hợp đồng hàng tháng linh hoạt mà không yêu cầu cam kết dài hạn.</p>", "section_2_body": "<h3>Có yêu cầu tiền đặt cọc hoặc tiền bảo đảm không?</h3><p>Có, một khoản tiền đặt cọc tương đương với 4 tuần tiền thuê được yêu cầu khi ký hợp đồng. Khoản tiền này được giữ theo luật thuê nhà của bang Victoria và sẽ được hoàn trả vào cuối thời gian lưu trú của bạn, với điều kiện phòng được để lại trong tình trạng tốt.</p><h3>Hóa đơn có được bao gồm trong giá thuê hàng tuần không?</h3><p>Có, tiền điện, nước, gas và internet tốc độ cao đều được bao gồm trong tiền thuê hàng tuần của bạn. Không có chi phí ẩn.</p><h3>Làm thế nào để tôi thanh toán tiền thuê?</h3><p>Tiền thuê được thanh toán hàng tuần hoặc hai tuần một lần qua chuyển khoản ngân hàng hoặc thẻ tín dụng. Bạn sẽ nhận được hóa đơn qua cổng thông tin trực tuyến của bạn mỗi chu kỳ thanh toán.</p>", "section_3_body": "<h3>Chỗ ở của bạn có dành cho sinh viên quốc tế không?</h3><p>Chắc chắn rồi — sinh viên quốc tế là cộng đồng chính của chúng tôi. Chúng tôi có đội ngũ nhân viên đa ngôn ngữ (Hàn Quốc, Nhật Bản, Trung Quốc, Thái Lan), và các phòng của chúng tôi được thiết kế để giúp bạn chuyển đến Melbourne một cách thoải mái nhất.</p><h3>Tôi cần cung cấp những tài liệu gì?</h3><p>Thông thường, bạn sẽ cần một bản sao hộ chiếu, thẻ sinh viên hoặc thư nhập học, và bằng chứng tài chính. Đội ngũ của chúng tôi sẽ hướng dẫn bạn chính xác những gì cần thiết.</p><h3>Tôi có thể cho khách ở qua đêm không?</h3><p>Khách qua đêm được phép với thông báo trước cho ban quản lý, tối đa 2 đêm liên tiếp. Các kỳ lưu trú dài hơn phải được phê duyệt.</p>", "section_1_title": "Đặt Phòng & Phòng Ở", "section_2_title": "Thanh Toán & Tiền Đặt Cọc", "section_3_title": "Hỗ Trợ Sinh Viên"}', 'Câu hỏi thường gặp — MillionStay Chỗ ở cho sinh viên tại Melbourne', 'Giải đáp các câu hỏi thường gặp về đặt phòng, thanh toán, hóa đơn, tiền đặt cọc và hỗ trợ sinh viên tại MillionStay Melbourne.', 'MillionStay câu hỏi thường gặp, câu hỏi về chỗ ở sinh viên tại Melbourne, câu hỏi đặt phòng, tiền thuê bao gồm tiện ích', '2026-04-16 03:01:37.85579+00'),
	(26, 'faq', 'ja', '{"cta_body": "当チームがサポートいたします。お問い合わせいただければ、24時間以内にご返信いたします。", "cta_title": "まだご質問がありますか？", "cta_button": "お問い合わせ", "hero_title": "よくある質問", "hero_subtitle": "ご質問がありますか？", "section_1_body": "<h3>MillionStayで部屋を予約するにはどうすればいいですか？</h3><p>Locationページで利用可能な部屋をご覧いただき、各リスティングから直接お問い合わせまたは申請を送信できます。当チームが24時間以内に空室状況を確認し、次のステップをご案内いたします。</p><h3>家賃に含まれるものは何ですか？</h3><p>すべての部屋にはWi-Fi、光熱費（電気、水道、ガス）、共用エリアの週1回の清掃、共用キッチンとランドリー施設の利用が含まれています。</p><h3>予約前に部屋を見ることはできますか？</h3><p>はい！対面およびバーチャルツアーの両方をご用意しています。海外から到着する留学生向けには、詳細なビデオウォークスルーを手配することも可能です。</p><h3>最低滞在期間はどのくらいですか？</h3><p>通常、最低滞在期間は4週間（1か月）です。長期契約の義務がない柔軟な月単位の契約を提供しています。</p>", "section_2_body": "<h3>保証金やデポジットは必要ですか？</h3><p>はい、契約時に4週間分の家賃に相当する保証金が必要です。この保証金はビクトリア州の賃貸法に基づいて保管され、滞在終了時に部屋が良好な状態であれば返金されます。</p><h3>週ごとの料金に光熱費は含まれていますか？</h3><p>はい、電気、水道、ガス、高速インターネットはすべて週ごとの家賃に含まれています。隠れた費用はありません。</p><h3>家賃の支払い方法は？</h3><p>家賃は週ごとまたは2週間ごとに銀行振込またはクレジットカードでお支払いいただけます。各請求サイクルごとにオンラインポータルを通じて請求書をお送りします。</p>", "section_3_body": "<h3>留学生向けのサービスはありますか？</h3><p>もちろんです。留学生は私たちの主要なコミュニティです。多言語対応のスタッフ（韓国語、日本語、中国語、タイ語）が在籍しており、メルボルンへの移行が快適になるよう設計された部屋をご用意しています。</p><h3>どのような書類が必要ですか？</h3><p>通常、パスポートのコピー、学生証または入学許可書、資金証明が必要です。必要な書類については当チームが具体的にご案内いたします。</p><h3>ゲストの宿泊は可能ですか？</h3><p>事前に管理者へ通知いただければ、ゲストの宿泊が可能です。最大2泊まで連続で宿泊できます。長期滞在の場合は承認が必要です。</p>", "section_1_title": "予約とお部屋について", "section_2_title": "お支払いと保証金", "section_3_title": "学生サポート"}', 'FAQ — MillionStay 学生宿泊施設 メルボルン', 'MillionStay メルボルンでの予約、支払い、光熱費、保証金、学生サポートに関するよくある質問への回答です。', 'MillionStay FAQ, 学生宿泊施設 質問 メルボルン, 予約 FAQ, 家賃 光熱費込み', '2026-04-16 03:01:38.412501+00'),
	(27, 'contact', 'zh', '{"email": "info@millionstay.com", "hours": "周一至周五: 上午9:00 – 下午6:00\n周六: 上午10:00 – 下午4:00\n周日: 休息", "phone": "+61 3 9000 0000", "address": "5层, 123 Collins Street\n墨尔本 VIC 3000\n澳大利亚", "form_title": "发送信息给我们", "hero_title": "联系我们", "email_label": "邮箱", "hours_label": "营业时间", "phone_label": "电话", "address_title": "办公地址", "form_subtitle": "关于我们的房间、预订流程或住宿计划有任何疑问吗？我们的多语言团队随时为您提供帮助——支持英语、韩语、中文、日语或泰语。", "hero_subtitle": "我们期待您的来信"}', '联系 MillionStay — 墨尔本学生住宿', '联系 MillionStay。我们会在24小时内以英语、韩语、中文、日语和泰语回复您的咨询。', '联系 MillionStay 墨尔本, 学生住宿咨询, 墨尔本多语言支持', '2026-04-16 03:01:40.754489+00'),
	(28, 'contact', 'ko', '{"email": "info@millionstay.com", "hours": "월요일 – 금요일: 오전 9시 – 오후 6시\n토요일: 오전 10시 – 오후 4시\n일요일: 휴무", "phone": "+61 3 9000 0000", "address": "Level 5, 123 Collins Street\nMelbourne VIC 3000\nAustralia", "form_title": "메시지 보내기", "hero_title": "문의하기", "email_label": "이메일", "hours_label": "영업 시간", "phone_label": "전화번호", "address_title": "사무실 주소", "form_subtitle": "객실, 예약 절차 또는 숙박 계획에 대해 궁금한 점이 있으신가요? 저희 다국어 팀이 영어, 한국어, 중국어, 일본어 또는 태국어로 도와드립니다.", "hero_subtitle": "여러분의 소중한 의견을 기다립니다"}', 'MillionStay 연락하기 — 멜버른 학생 숙소', 'MillionStay에 문의하십시오. 영어, 한국어, 중국어, 일본어 및 태국어로 24시간 이내에 답변 드립니다.', 'MillionStay 연락하기 멜버른, 학생 숙소 문의, 멜버른 다국어 지원', '2026-04-16 03:01:41.119209+00'),
	(29, 'contact', 'ja', '{"email": "info@millionstay.com", "hours": "月曜日～金曜日: 午前9時～午後6時\n土曜日: 午前10時～午後4時\n日曜日: 定休日", "phone": "+61 3 9000 0000", "address": "レベル5, 123 Collins Street\nMelbourne VIC 3000\nオーストラリア", "form_title": "メッセージを送る", "hero_title": "お問い合わせ", "email_label": "メールアドレス", "hours_label": "営業時間", "phone_label": "電話番号", "address_title": "オフィス住所", "form_subtitle": "お部屋、予約手続き、または滞在プランについてご質問がありますか？私たちの多言語対応チームが、英語、韓国語、中国語、日本語、またはタイ語でお手伝いします。", "hero_subtitle": "ぜひお気軽にご連絡ください"}', 'MillionStayへのお問い合わせ — メルボルン学生宿泊施設', 'MillionStayへのお問い合わせをお待ちしております。英語、韓国語、中国語、日本語、タイ語で対応しており、24時間以内に返信いたします。', 'MillionStayお問い合わせ メルボルン, 学生宿泊施設問い合わせ, メルボルン多言語サポート', '2026-04-16 03:01:41.147475+00'),
	(30, 'contact', 'vi', '{"email": "info@millionstay.com", "hours": "Thứ Hai – Thứ Sáu: 9:00 AM – 6:00 PM\nThứ Bảy: 10:00 AM – 4:00 PM\nChủ Nhật: Nghỉ", "phone": "+61 3 9000 0000", "address": "Tầng 5, 123 Collins Street\nMelbourne VIC 3000\nAustralia", "form_title": "Gửi Tin Nhắn Cho Chúng Tôi", "hero_title": "Liên Hệ Với Chúng Tôi", "email_label": "Email", "hours_label": "Giờ Làm Việc", "phone_label": "Điện Thoại", "address_title": "Địa Chỉ Văn Phòng", "form_subtitle": "Bạn có câu hỏi về phòng ở, quy trình đặt chỗ, hoặc kế hoạch lưu trú? Đội ngũ đa ngôn ngữ của chúng tôi sẵn sàng hỗ trợ bạn — bằng tiếng Anh, tiếng Hàn, tiếng Trung, tiếng Nhật hoặc tiếng Thái.", "hero_subtitle": "Chúng tôi rất mong nhận được phản hồi từ bạn"}', 'Liên hệ MillionStay — Chỗ ở cho sinh viên tại Melbourne', 'Liên hệ với MillionStay. Chúng tôi sẽ phản hồi trong vòng 24 giờ bằng các ngôn ngữ: tiếng Anh, tiếng Hàn, tiếng Trung, tiếng Nhật và tiếng Thái.', 'liên hệ MillionStay Melbourne, yêu cầu chỗ ở cho sinh viên, hỗ trợ đa ngôn ngữ Melbourne', '2026-04-16 03:01:41.365532+00');
