	(33, 'Career – Hotel Internship (Paid)', 'Paid hotel industry internship placement. Includes job matching, placement coordination and ongoing support throughout the internship period.', 'one_time', 1400, 'AUD', true, false, 'at_booking', false, false, NULL, false, NULL, false, NULL, true, 90, 'Inactive', '2026-04-10 10:04:20.016691+00', '2026-04-10 10:04:20.016691+00', NULL, NULL),
